import { useState } from "react";

function Compteur() {
  const [valeur, setValeur] = useState(0);

  return (
    <div>
      <p>Valeur : {valeur}</p>
      <button type="button" onClick={() => setValeur(valeur + 1)}>
        Incrémenter
      </button>
    </div>
  );
}

// Formulaire contrôlé
function Recherche({ onEnvoyer }) {
  const [texte, setTexte] = useState("");

  return (
    <form onSubmit={(e) => { e.preventDefault(); onEnvoyer(texte); }}>
      <label htmlFor="q">Rechercher</label>
      <input
        id="q"
        value={texte}
        onChange={(e) => setTexte(e.target.value)}
      />
      <button type="submit">Chercher</button>
    </form>
  );
}

function ListeTaches({ taches, onBasculer }) {
  if (taches.length === 0) {
    return <p>Aucune tâche pour le moment.</p>;
  }

  return (
    <ul>
      {taches.map((tache) => (
        <li key={tache.id}>
          <label>
            <input
              type="checkbox"
              checked={tache.faite}
              onChange={() => onBasculer(tache.id)}
            />
            {tache.titre}
          </label>
        </li>
      ))}
    </ul>
  );
}

import { useEffect, useState } from "react";

function Produits({ categorie }) {
  const [etat, setEtat] = useState({ chargement: true, donnees: [], erreur: null });

  useEffect(() => {
    const controleur = new AbortController();
    setEtat({ chargement: true, donnees: [], erreur: null });

    fetch(`/api/produits?categorie=${categorie}`, { signal: controleur.signal })
      .then((r) => {
        if (!r.ok) throw new Error(`Erreur ${r.status}`);
        return r.json();
      })
      .then((donnees) => setEtat({ chargement: false, donnees, erreur: null }))
      .catch((erreur) => {
        if (erreur.name !== "AbortError") setEtat({ chargement: false, donnees: [], erreur });
      });

    return () => controleur.abort();
  }, [categorie]);

  if (etat.chargement) return <p>Chargement…</p>;
  if (etat.erreur) return <p>Impossible de charger les produits.</p>;
  return <ul>{etat.donnees.map((p) => <li key={p.id}>{p.nom}</li>)}</ul>;
}

// Le parent détient l'état, les enfants le reçoivent
function Page() {
  const [filtre, setFiltre] = useState("");
  return (
    <>
      <Recherche valeur={filtre} onChange={setFiltre} />
      <Liste filtre={filtre} />
    </>
  );
}

import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";

test("incrémente au clic", async () => {
  render(<Compteur />);
  await userEvent.click(screen.getByRole("button", { name: /incrémenter/i }));
  expect(screen.getByText(/valeur : 1/i)).toBeInTheDocument();
});
